solutions.naive:
class Solution:
    def smallestGoodBase(self, n: str) -> str:
        N = int(n)
        for length in range(N.bit_length(), 2, -1):
            lo, hi = 2, N - 1
            while lo <= hi:
                base = (lo + hi) // 2
                total = 0
                for _ in range(length):
                    total = total * base + 1
                    if total > N:
                        break
                if total == N:
                    return str(base)
                if total < N:
                    lo = base + 1
                else:
                    hi = base - 1
        return str(N - 1)

