class Solution:
    def smallestGoodBase(self, n: str) -> str:
        N = int(n)
        max_m = N.bit_length() - 1
        for m in range(max_m, 1, -1):
            k = int(N ** (1.0 / m))
            for base in range(max(2, k - 2), k + 3):
                total, cur = 1, 1
                for _ in range(m):
                    cur *= base
                    total += cur
                    if total > N:
                        break
                if total == N:
                    return str(base)
        return str(N - 1)

